import { json, noContent, parseJsonBody, preconditions, NO_STORE } from "../http.mjs";
import { getJson, putJson, headObject, deleteObject } from "../store.mjs";
import { policyKey } from "../policy.mjs";
import { invalidRequestBody, notFound } from "../problems.mjs";

// .../policy at the Space, Collection and Resource scopes: one
// implementation, the scope coming from the ids the route resolved. A policy
// document is stored under policies/ (never public, never listed) and
// versioned by its ETag like every other sub-resource.

export async function getPolicy(req, { spaceId, collectionId, resourceId }) {
  const stored = await getJson(spaceId, policyKey({ collectionId, resourceId }));
  if (stored === null) {
    throw notFound();
  }
  return json(req, 200, stored.doc, { ETag: stored.etag });
}

export async function putPolicy(req, { spaceId, collectionId, resourceId }) {
  const key = policyKey({ collectionId, resourceId });
  const policy = parseJsonBody(req, { problem: invalidRequestBody });
  if (typeof policy.type !== "string" || !policy.type) {
    throw invalidRequestBody('A policy must have a string "type".');
  }
  const existed = (await headObject(spaceId, key)) !== null;
  const { etag } = await putJson(spaceId, key, policy, preconditions(req));
  return json(req, existed ? 200 : 201, policy, { ...NO_STORE, ETag: etag });
}

// Idempotent: reverting to capability-only access.
export async function deletePolicy(req, { spaceId, collectionId, resourceId }) {
  const key = policyKey({ collectionId, resourceId });
  if ((await headObject(spaceId, key)) !== null) {
    await deleteObject(spaceId, key, preconditions(req));
  }
  return noContent(req, NO_STORE);
}
